class Solution:
    def convoys(self, depot: int, position: List[int], speed: List[int]) -> int:
        count = 0
        for i in range(len(position)):
            di = depot - position[i]
            leads = True
            for j in range(len(position)):
                dj = depot - position[j]
                if position[j] > position[i] and dj * speed[i] >= di * speed[j]:
                    leads = False
                    break
            if leads:
                count += 1
        return count

