class Solution {
    public int convoys(int depot, int[] position, int[] speed) {
        int count = 0;
        for (int i = 0; i < position.length; i++) {
            long di = depot - position[i];
            boolean leads = true;
            for (int j = 0; j < position.length && leads; j++) {
                long dj = depot - position[j];
                if (position[j] > position[i] && dj * speed[i] >= di * speed[j]) leads = false;
            }
            if (leads) count++;
        }
        return count;
    }
}

