class Solution {
    public int convoys(int depot, int[] position, int[] speed) {
        int n = position.length;
        long[] trucks = new long[n];
        for (int i = 0; i < n; i++) trucks[i] = (long) position[i] << 20 | speed[i];
        Arrays.sort(trucks);
        int count = 0;
        long leadDist = 0, leadSpeed = 1;
        for (int k = n - 1; k >= 0; k--) {
            long dist = depot - (trucks[k] >> 20), s = trucks[k] & ((1 << 20) - 1);
            if (dist * leadSpeed > leadDist * s) {
                count++;
                leadDist = dist;
                leadSpeed = s;
            }
        }
        return count;
    }
}

