typedef struct { int p, s; } Truck;

static int nearestFirst(const void* a, const void* b) {
    return ((const Truck*)b)->p - ((const Truck*)a)->p;
}

int convoys(int depot, int* position, int positionSize, int* speed, int speedSize) {
    Truck* trucks = malloc(positionSize * sizeof(Truck));
    for (int i = 0; i < positionSize; i++) trucks[i] = (Truck){position[i], speed[i]};
    qsort(trucks, positionSize, sizeof(Truck), nearestFirst);
    int count = 0;
    long long leadDist = 0, leadSpeed = 1;
    for (int k = 0; k < positionSize; k++) {
        long long dist = depot - trucks[k].p;
        if (dist * leadSpeed > leadDist * trucks[k].s) {
            count++;
            leadDist = dist;
            leadSpeed = trucks[k].s;
        }
    }
    free(trucks);
    return count;
}
